types.SM.IncreasingBoundaryTriple.gapCompositi:
SM.IncreasingBoundaryTriple.gapCompositionEquiv_left_cuts {n : ℕ} [NeZero n] (t : SM.IncreasingBoundaryTriple n)
  (π : t.MiddleComposition) :
  (t.gapCompositionEquiv π).1.cutSet.cuts = {x ∈ (↑π).cutSet.cuts | t.lower ≤ x ∧ x ≤ t.middle}

SM.IncreasingBoundaryTriple.gapCompositionEquiv_right_cuts {n : ℕ} [NeZero n] (t : SM.IncreasingBoundaryTriple n)
  (π : t.MiddleComposition) :
  (t.gapCompositionEquiv π).2.cutSet.cuts = {x ∈ (↑π).cutSet.cuts | t.middle ≤ x ∧ x ≤ t.upper}

types.SM.IntervalComposition.existsUnique_farT:
SM.IntervalComposition.existsUnique_farTriple_iff {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (t : SM.IncreasingBoundaryTriple n) :
  (∃! k, π.farTriple k = t) ↔ I = t.spanInterval ∧ t.middle ∈ π.cutSet.cuts
